CREATE TABLE "Owner" ("id" TEXT PRIMARY KEY, "username" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "expiresAt" DOUBLE PRECISION NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL, "lastSeenAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "Session_ownerId_expiresAt_idx" ON "Session"("ownerId","expiresAt");
CREATE TABLE "Mission" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "goal" TEXT NOT NULL, "steps" JSONB NOT NULL, "planHash" TEXT NOT NULL, "actions" JSONB NOT NULL, "status" TEXT NOT NULL, "approvalId" TEXT, "verification" JSONB, "createdAt" DOUBLE PRECISION NOT NULL, "updatedAt" DOUBLE PRECISION NOT NULL, "verifiedAt" DOUBLE PRECISION);
CREATE INDEX "Mission_ownerId_updatedAt_idx" ON "Mission"("ownerId","updatedAt");
CREATE TABLE "Approval" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "missionId" TEXT NOT NULL REFERENCES "Mission"("id") ON DELETE CASCADE, "planHash" TEXT NOT NULL, "actions" JSONB NOT NULL, "status" TEXT NOT NULL, "requestedBy" TEXT NOT NULL, "requestedAt" DOUBLE PRECISION NOT NULL, "expiresAt" DOUBLE PRECISION NOT NULL, "approvedBy" TEXT, "approvedAt" DOUBLE PRECISION, "tokenJti" TEXT, "tokenExpiresAt" DOUBLE PRECISION, "usedAt" DOUBLE PRECISION);
CREATE INDEX "Approval_ownerId_missionId_status_idx" ON "Approval"("ownerId","missionId","status");
CREATE TABLE "MissionRun" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "missionId" TEXT NOT NULL REFERENCES "Mission"("id") ON DELETE CASCADE, "action" TEXT NOT NULL, "result" JSONB NOT NULL, "verification" JSONB NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL, "executionMode" TEXT NOT NULL);
CREATE INDEX "MissionRun_ownerId_missionId_createdAt_idx" ON "MissionRun"("ownerId","missionId","createdAt");
CREATE TABLE "Memory" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "content" TEXT NOT NULL, "importance" DOUBLE PRECISION NOT NULL DEFAULT 0.5, "createdAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "Memory_ownerId_createdAt_idx" ON "Memory"("ownerId","createdAt");
CREATE TABLE "CompanionEvent" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "message" TEXT NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "CompanionEvent_ownerId_createdAt_idx" ON "CompanionEvent"("ownerId","createdAt");
CREATE TABLE "Dataset" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "provider" TEXT, "title" TEXT, "status" TEXT, "data" JSONB NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL, "updatedAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "Dataset_ownerId_createdAt_idx" ON "Dataset"("ownerId","createdAt");
CREATE INDEX "Dataset_ownerId_status_idx" ON "Dataset"("ownerId","status");
CREATE TABLE "KnowledgeGraphSnapshot" ("ownerId" TEXT PRIMARY KEY REFERENCES "Owner"("id") ON DELETE CASCADE, "nodes" JSONB NOT NULL, "edges" JSONB NOT NULL, "updatedAt" DOUBLE PRECISION NOT NULL, "memoryCount" INTEGER NOT NULL);
CREATE TABLE "TelemetryEvent" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "category" TEXT NOT NULL, "payload" JSONB NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "TelemetryEvent_ownerId_category_createdAt_idx" ON "TelemetryEvent"("ownerId","category","createdAt");
CREATE TABLE "WebAuthnCredential" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "publicKey" JSONB NOT NULL, "counter" INTEGER NOT NULL, "transports" JSONB NOT NULL, "createdAt" DOUBLE PRECISION NOT NULL, "lastUsedAt" DOUBLE PRECISION);
CREATE INDEX "WebAuthnCredential_ownerId_idx" ON "WebAuthnCredential"("ownerId");
CREATE TABLE "WebAuthnChallenge" ("id" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL REFERENCES "Owner"("id") ON DELETE CASCADE, "challenge" TEXT NOT NULL, "area" TEXT, "mode" TEXT, "createdAt" DOUBLE PRECISION NOT NULL);
CREATE INDEX "WebAuthnChallenge_ownerId_createdAt_idx" ON "WebAuthnChallenge"("ownerId","createdAt");
